        let a = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
        let b = Version::parse("1.2.3+abc", VersionGrammar::SemVer).unwrap();
        assert_ne!(a, b);
        assert_eq!(a.compare(&b).unwrap(), Ordering::Equal);
