mod severity;
pub use severity::{Severity, SeverityParseError};

mod version;
pub use version::{GrammarMismatch, Version, VersionGrammar, VersionParseError};

use serde::{Deserialize, Serialize};

/// §7.7. `SemVer` is the only grammar with an implementation in the committed v0.1–v0.4
/// scope; the rest are declared so `Ecosystem::version_grammar` is total.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub enum VersionGrammar {
    SemVer,
    /// PEP 440 (§7.7) — declared, not implemented.
    Pep440,
    /// Maven's qualifier-ordering comparator (§7.7) — declared, not implemented.
    Maven,
}

/// The parsed form, kept alongside `raw` so comparison and component access are cheap.
/// `SemVer` is the only inhabited variant until a demand-gated grammar ships (§7.7).
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) enum ParsedVersion {
    SemVer(semver::Version),
}

/// A parsed version, tagged with the grammar it was parsed under. §7.7, P4.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Version {
    pub(crate) grammar: VersionGrammar,
    /// The exact string this version was parsed from, preserved so a write-back can be
    /// byte-identical when nothing changed. `render()` returns this verbatim.
    pub(crate) raw: String,
    pub(crate) parsed: ParsedVersion,
}

impl Version {
    pub fn parse(raw: &str, grammar: VersionGrammar) -> Result<Self, VersionParseError> {
        match grammar {
            VersionGrammar::SemVer => {
                let parsed = semver::Version::parse(raw).map_err(|e| VersionParseError {
                    raw: raw.to_string(),
                    grammar,
                    message: e.to_string(),
                })?;
                Ok(Version { grammar, raw: raw.to_string(), parsed: ParsedVersion::SemVer(parsed) })
            }
            VersionGrammar::Pep440 | VersionGrammar::Maven => Err(VersionParseError {
                raw: raw.to_string(),
                grammar,
                message: format!("{grammar:?} has no versioning implementation yet (§7.7)"),
            }),
        }
    }

    /// Construct a `SemVer`-grammar version directly from numeric components, canonically
    /// rendered (`{major}.{minor}.{patch}`, no prerelease/build metadata) — what
    /// `bump_version` (§F.6.2) needs, since a bump computes new numeric components rather
    /// than re-parsing a string.
    pub fn semver(major: u64, minor: u64, patch: u64) -> Self {
        let parsed = semver::Version::new(major, minor, patch);
        Version { grammar: VersionGrammar::SemVer, raw: parsed.to_string(), parsed: ParsedVersion::SemVer(parsed) }
    }

    pub fn grammar(&self) -> VersionGrammar {
        self.grammar
    }

    /// The original string. `render()` and the input to `parse` round-trip byte-identically
    /// for any version this crate produced by parsing.
    pub fn render(&self) -> &str {
        &self.raw
    }

    /// SemVer component access. **Defined only for `VersionGrammar::SemVer`** — `None` for any
    /// other grammar, rather than a guess.
    pub fn major(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.major),
        }
    }

    pub fn minor(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.minor),
        }
    }

    pub fn patch(&self) -> Option<u64> {
        match &self.parsed {
            ParsedVersion::SemVer(v) => Some(v.patch),
        }
    }

    pub fn is_prerelease(&self) -> bool {
        match &self.parsed {
            ParsedVersion::SemVer(v) => !v.pre.is_empty(),
        }
    }

    /// Grammar-aware ordering. `Err(GrammarMismatch)` when the two versions were parsed
    /// under different grammars.
    pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
        if self.grammar != other.grammar {
            return Err(GrammarMismatch { left: self.grammar, right: other.grammar });
        }
        match (&self.parsed, &other.parsed) {
            (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => Ok(a.cmp(b)),
        }
    }

    /// Convenience for the very common "both operands are SemVer" case; `None` on mismatch.
    pub fn partial_compare(&self, other: &Version) -> Option<std::cmp::Ordering> {
        self.compare(other).ok()
    }
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("`{raw}` is not a valid {grammar:?} version: {message}")]
pub struct VersionParseError {
    pub raw: String,
    pub grammar: VersionGrammar,
    pub message: String,
}

#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("cannot compare a {left:?} version with a {right:?} version")]
pub struct GrammarMismatch {
    pub left: VersionGrammar,
    pub right: VersionGrammar,
}

