/// Grammar-aware ordering. `Err(GrammarMismatch)` when the two versions were parsed
/// under different grammars.
///
/// For SemVer this is true *precedence*, not `semver::Version`'s own derived `Ord` —
/// that crate's `Ord` factors in build metadata as a total-order tiebreaker (so
/// `1.2.3 < 1.2.3+abc` under it), which is not SemVer precedence at all: the spec is
/// explicit that build metadata "MUST be ignored when determining version precedence."
/// Comparing `(major, minor, patch, pre)` tuples directly is what actually ignores it —
/// `Prerelease`'s own `Ord` already implements the numeric-vs-alphanumeric identifier
/// rule correctly, so nothing further is needed there.
pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
    if self.grammar != other.grammar {
        return Err(GrammarMismatch { left: self.grammar, right: other.grammar });
    }
    match (&self.parsed, &other.parsed) {
        (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => {
            Ok((a.major, a.minor, a.patch, &a.pre).cmp(&(b.major, b.minor, b.patch, &b.pre)))
        }
    }
}

