22	/// Trait implemented by per-ecosystem manifest editors.
23	pub trait Manifest: Send + Sync {
24	    fn path(&self) -> &Path;
25	    fn ecosystem(&self) -> Ecosystem;
26	    fn role(&self) -> ManifestRole;
27	    fn package_name(&self) -> Result<String, ManifestError>;
28	    fn current_version(&self) -> Result<Version, ManifestError>;
29	    fn write_version(&mut self, v: &Version) -> Result<(), ManifestError>;
30	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
31	    fn update_dependency_spec(
32	        &mut self,
33	        name: &str,
34	        kind: callisto_model::DepKind,
35	        new: DepSpec,
36	    ) -> Result<(), ManifestError>;
37	    fn is_publishable(&self) -> bool {
38	        true
39	    }
40	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
41	        if !self.is_publishable() {
42	            return vec![callisto_model::PublishTarget::None];
