89	/// Opens a manifest file matching `decl.format`.
90	pub fn open(
91	    decl: &ManifestDecl,
92	    ctx: &OpenContext<'_>,
93	) -> Result<Box<dyn Manifest>, ManifestError> {
94	    if decl.role == ManifestRole::Lockfile {
95	        return Err(ManifestError::ReadOnlyFormat {
96	            path: decl.path.clone(),
97	            format: decl.format,
98	            reason: "lockfiles are regenerated via subprocess (§7.6 step 9), never opened as a Manifest handle",
99	        });
100	    }
101	
102	    match decl.format {
103	        #[cfg(feature = "cargo")]
104	        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
105	        #[cfg(feature = "npm")]
106	        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
107	        other => Err(ManifestError::ReadOnlyFormat {
108	            path: decl.path.clone(),
109	            format: other,
110	            reason: "not implemented — demand-gated per §2.2",
111	        }),
112	    }
113	}
