16	pub struct CascadeDecision {
17	    pub severity: Severity,
18	    pub rewrite: bool,
19	    pub governed_by: Option<ConfigKey>,
20	    pub escalated: bool,
21	    pub unknown_coverage: bool,
22	}
23	
24	pub fn cascade_action(
25	    kind: DepKind,
26	    coverage: Coverage,
27	    _source: Severity,
28	    cfg: &CascadeConfig,
29	) -> CascadeDecision {
30	    use Coverage::*;
31	    use DepKind::*;
32	
33	    let effective = match (cfg.mode, coverage) {
34	        (CascadeMode::Always, _) => DoesNotCover,
35	        (CascadeMode::OutOfRange, Covers) => Covers,
36	        (CascadeMode::OutOfRange, DoesNotCover) => DoesNotCover,
37	        (CascadeMode::OutOfRange, Unknown) => Covers,
38	    };
39	
40	    let rewrite = matches!(coverage, DoesNotCover);
41	
42	    let (severity, governed_by, escalated) = match (kind, effective) {
43	        (Runtime | Optional | Build, Covers) => (Severity::None, None, false),
44	        (Runtime | Optional | Build, DoesNotCover) => (
45	            cfg.bump_severity.as_severity(),
46	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
47	            false,
48	        ),
49	        (Peer, Covers) => (Severity::None, None, false),
50	        (Peer, DoesNotCover) if cfg.peer_escalation && matches!(coverage, DoesNotCover) => (
51	            Severity::Major,
52	            Some(ConfigKey::CASCADE_PEER_ESCALATION),
53	            true,
54	        ),
55	        (Peer, DoesNotCover) => (
56	            cfg.bump_severity.as_severity(),
57	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
58	            false,
59	        ),
60	        (Dev, _) => (Severity::None, None, false),
61	        _ => (Severity::None, None, false),
62	    };
63	
64	    let governed_by = match (cfg.mode, coverage, severity) {
65	        (CascadeMode::Always, Covers | Unknown, s) if s != Severity::None => {
66	            Some(ConfigKey::CASCADE_MODE)
67	        }
68	        _ => governed_by,
69	    };
70	
71	    CascadeDecision {
72	        severity,
73	        rewrite,
74	        governed_by,
75	        escalated,
76	        unknown_coverage: matches!(coverage, Unknown),
77	    }
78	}
