80	pub fn coverage(spec: &DepSpec, new: &Version) -> Result<Coverage, GrammarMismatch> {
81	    match spec {
82	        DepSpec::Exact(v) => {
83	            if v == new {
84	                Ok(Coverage::Covers)
85	            } else {
86	                Ok(Coverage::DoesNotCover)
87	            }
88	        }
89	        DepSpec::CargoBare(v) => {
90	            if caret_covers(v, new)? {
91	                Ok(Coverage::Covers)
92	            } else {
93	                Ok(Coverage::DoesNotCover)
94	            }
95	        }
96	        DepSpec::Range(req, _) => {
97	            if req.matches(new)? {
98	                Ok(Coverage::Covers)
99	            } else {
100	                Ok(Coverage::DoesNotCover)
101	            }
102	        }
103	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
104	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
105	    }
106	}
107	
108	pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
109	    let cmp = Version::compare(new, cur)?;
110	    if cmp.is_lt() {
111	        return Ok(false);
112	    }
113	    let cur_maj = cur.major().unwrap_or(0);
114	    let cur_min = cur.minor().unwrap_or(0);
115	    let new_maj = new.major().unwrap_or(0);
116	    let new_min = new.minor().unwrap_or(0);
117	
118	    if cur_maj > 0 {
119	        Ok(new_maj == cur_maj)
120	    } else if cur_min > 0 {
121	        Ok(new_maj == 0 && new_min == cur_min)
122	    } else {
123	        Ok(new == cur)
124	    }
125	}
