138	#[derive(Clone, Debug, Default)]
139	pub struct CascadeOutcome {
140	    pub severities: BTreeMap<PackageId, Severity>,
141	    pub targets: BTreeMap<PackageId, Version>,
142	    pub reasons: BTreeMap<PackageId, BumpReason>,
143	    pub governed_by: BTreeMap<PackageId, ConfigKey>,
144	    pub rewrites: BTreeMap<RewriteKey, SpecRewrite>,
145	    pub diagnostics: Vec<Diagnostic>,
146	    pub iterations: usize,
147	}
148	
149	/// Trait for dependency graph cascade solving.
150	pub trait CascadeSolver<D: DependencyResolver> {
151	    fn solve_cascade(&self, input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError>;
152	}
153	
154	pub fn run_cascade<D: DependencyResolver>(
155	    input: CascadeInput<'_, D>,
156	) -> Result<CascadeOutcome, GraphError> {
157	    solve_cascade(input)
158	}
159	
160	pub fn solve_cascade<D: DependencyResolver>(
161	    input: CascadeInput<'_, D>,
162	) -> Result<CascadeOutcome, GraphError> {
163	    let mut out = CascadeOutcome {
164	        severities: input.seed.clone(),
165	        reasons: input.reasons.clone(),
166	        ..Default::default()
167	    };
168	
169	    for (id, &sev) in input.seed {
170	        let t = bump_target(id, sev, &input)?;
171	        out.targets.insert(id.clone(), t);
172	    }
173	
174	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
175	    let mut iterations = 0;
176	    let bound = convergence_bound(input.graph.packages().count());
177	
178	    let mut changed = true;
179	    while changed {
180	        changed = false;
181	
182	        while let Some(pkg) = worklist.pop_first() {
183	            iterations += 1;
184	            if iterations > bound {
185	                return Err(GraphError::CascadeNotConverged { iterations });
186	            }
187	
188	            let new_version = out.targets[&pkg].clone();
189	            let src_sev = out.severities[&pkg];
190	
191	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
192	            for edge in dependents {
193	                let cov = coverage(&edge.spec, &new_version).map_err(|source| {
194	                    GraphError::GrammarMismatch {
195	                        from: edge.from.clone(),
196	                        to: edge.to.clone(),
197	                        source,
198	                    }
199	                })?;
200	
201	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
202	
203	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
204	                    let code = match edge.spec {
205	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
206	                        _ => DiagnosticCode::RangeNotRoundTrippable,
207	                    };
208	                    out.diagnostics.push(Diagnostic {
209	                        code,
210	                        severity: DiagnosticSeverity::Warning,
211	                        message: format!(
212	                            "spec `{}` for `{}` could not be tested for coverage",
213	                            edge.spec.render(),
214	                            edge.to.display_name()
215	                        ),
216	                        package: Some(edge.from.clone()),
217	                        path: Some(edge.from_manifest.clone()),
218	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
219	                        escalated_by: None,
220	                    });
221	                }
222	
223	                if d.rewrite {
224	                    let eco = edge.from.ecosystem().unwrap_or_else(|| {
225	                        if edge.from_manifest.to_string_lossy().ends_with("Cargo.toml") {
226	                            Ecosystem::Cargo
227	                        } else {
228	                            Ecosystem::Npm
229	                        }
230	                    });
231	                    match rewrite_spec(&edge.spec, &new_version, eco, input.cfg) {
232	                        RewriteOutcome::Rewritten(to_spec) => {
233	                            let key = RewriteKey {
234	                                target: if edge.inherited {
235	                                    DepWriteTarget::CargoWorkspaceDependency {
236	                                        root_manifest: edge.from_manifest.clone(),
237	                                    }
238	                                } else {
239	                                    DepWriteTarget::Manifest(edge.from_manifest.clone())
240	                                },
241	                                name: edge.to.name().to_string(),
242	                                kind: if edge.inherited {
243	                                    None
244	                                } else {
245	                                    Some(edge.kind)
246	                                },
247	                            };
248	                            out.rewrites.insert(
249	                                key.clone(),
250	                                SpecRewrite {
251	                                    key,
252	                                    dependency: edge.to.clone(),
253	                                    from: edge.spec.clone(),
254	                                    to: to_spec,
255	                                },
256	                            );
257	                        }
258	                        RewriteOutcome::LeftAlone(dg) => {
259	                            out.diagnostics.push(dg);
260	                        }
261	                    }
262	                }
263	
264	                let cur_sev = out
265	                    .severities
266	                    .get(&edge.from)
267	                    .copied()
268	                    .unwrap_or(Severity::None);
269	                if d.severity > cur_sev {
270	                    raise(
271	                        &edge.from,
272	                        d.severity,
273	                        &d,
274	                        &pkg,
275	                        &edge,
276	                        &new_version,
277	                        &mut out,
278	                        input.groups,
279	                        &mut worklist,
280	                        &input,
281	                    )?;
282	                }
283	            }
284	        }
285	
286	        // Spec §G.6.7: Linked group release severity propagation
287	        for g in input.groups.linked.values() {
288	            let member_ids: Vec<PackageId> = g
289	                .members(crate::config::GroupMemberKind::Package)
290	                .filter_map(|m| match m {
291	                    crate::config::GroupMember::Package(ref id) => Some(id.clone()),
292	                    _ => None,
293	                })
294	                .collect();
295	
296	            let mut max_sev = Severity::None;
297	            for id in &member_ids {
298	                if let Some(&sev) = out.severities.get(id) {
299	                    max_sev = max_sev.max(sev);
300	                }
301	            }
302	
303	            if max_sev > Severity::None {
304	                for id in member_ids {
305	                    let cur_sev = out.severities.get(&id).copied().unwrap_or(Severity::None);
306	                    if max_sev > cur_sev {
307	                        out.severities.insert(id.clone(), max_sev);
308	                        let target = bump_target(&id, max_sev, &input)?;
309	                        out.targets.insert(id.clone(), target);
310	                        out.reasons.insert(
311	                            id.clone(),
312	                            BumpReason::LinkedGroupUnion {
313	                                group: g.name.clone(),
314	                            },
315	                        );
316	                        worklist.insert(id.clone());
317	                        changed = true;
318	                    }
319	                }
320	            }
321	        }
322	    }
323	
324	    out.iterations = iterations;
325	    Ok(out)
326	}
