329	pub(crate) fn calculate_bump_severity(from: &Version, to: &Version) -> Severity {
330	    if to.major().unwrap_or(0) > from.major().unwrap_or(0) {
331	        Severity::Major
332	    } else if to.minor().unwrap_or(0) > from.minor().unwrap_or(0) {
333	        Severity::Minor
334	    } else if to.patch().unwrap_or(0) > from.patch().unwrap_or(0)
335	        || to.is_prerelease()
336	        || to != from
337	    {
338	        Severity::Patch
339	    } else {
340	        Severity::None
341	    }
342	}
