366	#[allow(clippy::too_many_arguments)]
367	fn raise<D: DependencyResolver>(
368	    pkg: &PackageId,
369	    sev: Severity,
370	    decision: &CascadeDecision,
371	    via: &PackageId,
372	    edge: &DepEdge,
373	    dependency_to: &Version,
374	    out: &mut CascadeOutcome,
375	    groups: &GroupTable,
376	    worklist: &mut BTreeSet<PackageId>,
377	    input: &CascadeInput<'_, D>,
378	) -> Result<bool, GraphError> {
379	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
380	    if sev <= cur_sev {
381	        return Ok(false);
382	    }
383	
384	    out.severities.insert(pkg.clone(), sev);
385	
386	    let new_reason = if decision.escalated {
387	        BumpReason::PeerEscalation {
388	            via: via.clone(),
389	            spec: edge.spec.render(),
390	        }
391	    } else {
392	        BumpReason::Cascade {
393	            via: via.clone(),
394	            dep_kind: edge.kind,
395	            spec: edge.spec.render(),
396	            dependency_to: dependency_to.clone(),
397	        }
398	    };
399	    out.reasons.insert(pkg.clone(), new_reason);
400	
401	    if let Some(ref gov) = decision.governed_by {
402	        out.governed_by.insert(pkg.clone(), gov.clone());
403	    }
404	
405	    let new_t = bump_target(pkg, sev, input)?;
406	    out.targets.insert(pkg.clone(), new_t);
407	    worklist.insert(pkg.clone());
408	
409	    for sib in groups.fixed_siblings(pkg) {
410	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
411	        if sev > sib_sev {
412	            out.severities.insert(sib.clone(), sev);
413	            out.reasons.insert(
414	                sib.clone(),
415	                BumpReason::FixedGroupUnion {
416	                    group: groups.fixed_group_of(pkg).unwrap().name.clone(),
417	                },
418	            );
419	            let sib_t = bump_target(sib, sev, input)?;
420	            out.targets.insert(sib.clone(), sib_t);
421	            worklist.insert(sib.clone());
422	        }
423	    }
424	
425	    Ok(true)
426	}
