46	pub fn parse_pre_json(input: &str) -> Result<PreState, PreJsonError> {
47	    let clean_input = input.strip_prefix('\u{FEFF}').unwrap_or(input);
48	    let val: serde_json::Value =
49	        serde_json::from_str(clean_input).map_err(|e| PreJsonError::Malformed {
50	            message: e.to_string(),
51	        })?;
52	
53	    let obj = val.as_object().ok_or_else(|| PreJsonError::Malformed {
54	        message: "expected a JSON object".to_string(),
55	    })?;
56	
57	    let mode_val = obj
58	        .get("mode")
59	        .ok_or(PreJsonError::MissingField { field: "mode" })?;
60	    let mode_str = mode_val
61	        .as_str()
62	        .ok_or(PreJsonError::WrongFieldType { field: "mode" })?;
63	    let mode = match mode_str {
64	        "pre" => PreMode::Pre,
65	        "exit" => PreMode::Exit,
66	        _ => {
67	            return Err(PreJsonError::InvalidMode {
68	                found: mode_str.to_string(),
69	            })
70	        }
71	    };
72	
73	    let tag_val = obj
74	        .get("tag")
75	        .ok_or(PreJsonError::MissingField { field: "tag" })?;
76	    let tag = tag_val
77	        .as_str()
78	        .ok_or(PreJsonError::WrongFieldType { field: "tag" })?
79	        .to_string();
80	
81	    let init_val = obj
82	        .get("initialVersions")
83	        .ok_or(PreJsonError::MissingField {
84	            field: "initialVersions",
85	        })?;
86	    let init_obj = init_val.as_object().ok_or(PreJsonError::WrongFieldType {
87	        field: "initialVersions",
88	    })?;
89	
90	    let mut initial_versions = IndexMap::new();
91	    for (pkg, v_val) in init_obj {
92	        let v_str = v_val.as_str().ok_or(PreJsonError::WrongFieldType {
93	            field: "initialVersions",
94	        })?;
95	        let ver = Version::parse(v_str, VersionGrammar::SemVer).map_err(|source| {
96	            PreJsonError::InvalidInitialVersion {
97	                package: pkg.clone(),
98	                raw: v_str.to_string(),
99	                source,
100	            }
101	        })?;
102	        initial_versions.insert(pkg.clone(), ver);
103	    }
104	
105	    let cs_val = obj.get("changesets").ok_or(PreJsonError::MissingField {
106	        field: "changesets",
107	    })?;
108	    let cs_arr = cs_val.as_array().ok_or(PreJsonError::WrongFieldType {
109	        field: "changesets",
110	    })?;
111	
112	    let mut changesets = Vec::new();
113	    for (index, c_val) in cs_arr.iter().enumerate() {
114	        let c_str = c_val
115	            .as_str()
116	            .ok_or(PreJsonError::InvalidChangesetId { index })?;
117	        changesets.push(c_str.to_string());
118	    }
119	
120	    Ok(PreState {
121	        mode,
122	        tag,
123	        initial_versions,
124	        changesets,
125	    })
126	}
