56	            ));
57	        }
58	
59	        // Step 1: Package Selection
60	        println!("Which packages would you like to include in this changeset?");
61	        let selected_indices = MultiSelect::new()
62	            .items(&all_packages)
63	            .interact()
64	            .map_err(|e| CliError::Other(format!("Interactive selection failed: {e}")))?;
65	
66	        if selected_indices.is_empty() {
67	            return Err(CliError::Other(
68	                "No packages selected for changeset.".to_string(),
69	            ));
70	        }
71	
72	        let selected_packages: Vec<String> = selected_indices
73	            .into_iter()
