80	        let major_indices = MultiSelect::new()
81	            .items(&selected_packages)
82	            .interact()
83	            .map_err(|e| CliError::Other(format!("Interactive selection failed: {e}")))?;
84	
85	        let major_set: std::collections::HashSet<usize> = major_indices.into_iter().collect();
86	
87	        // Step 3: Minor Bump Selection (excluding major packages)
88	        let minor_candidates: Vec<String> = selected_packages
89	            .iter()
90	            .enumerate()
91	            .filter(|(idx, _)| !major_set.contains(idx))
92	            .map(|(_, name)| name.clone())
93	            .collect();
94	
95	        let minor_indices = if !minor_candidates.is_empty() {
96	            println!("\nWhich of these packages should be a MINOR bump?");
97	            println!("(Any remaining packages will default to a PATCH bump)");
98	            MultiSelect::new()
99	                .items(&minor_candidates)
100	                .interact()
101	                .map_err(|e| CliError::Other(format!("Interactive selection failed: {e}")))?
102	        } else {
103	            Vec::new()
104	        };
105	
106	        let minor_set: std::collections::HashSet<String> = minor_indices
107	            .into_iter()
108	            .map(|idx| minor_candidates[idx].clone())
109	            .collect();
110	
111	        // Build entries with assigned severities
112	        for (idx, pkg_name) in selected_packages.iter().enumerate() {
113	            let severity = if major_set.contains(&idx) {
