81	    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
82	        let rev = format!("{refname}^{{commit}}");
83	        let output = self.runner.run(
84	            "git",
85	            &["rev-parse", "--verify", "--quiet", &rev],
86	            &self.root,
87	        )?;
88	
89	        if !output.success() {
90	            return Ok(None);
91	        }
92	        let sha_str = output.stdout_trimmed();
93	        if sha_str.is_empty() {
94	            return Ok(None);
95	        }
96	        Ok(CommitSha::parse(sha_str).ok())
97	    }
