148	    fn create_tag(
149	        &self,
150	        name: &str,
151	        target_sha: &CommitSha,
152	        message: Option<&str>,
153	        _permit: &ApplyPermit,
154	    ) -> Result<(), VcsError> {
155	        let output = match message {
156	            Some(msg) => self.runner.run(
157	                "git",
158	                &["tag", "-a", name, "-m", msg, target_sha.as_str()],
159	                &self.root,
160	            )?,
161	            None => self
162	                .runner
163	                .run("git", &["tag", name, target_sha.as_str()], &self.root)?,
164	        };
165	        if !output.success() {
166	            return Err(VcsError::Git(format!(
167	                "`git tag` failed in `{}`: {}",
168	                self.root.display(),
169	                output.stderr
170	            )));
171	        }
172	        Ok(())
173	    }
