197	/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
198	/// produced by [`ShellGit::commits_since`] into [`GitCommit`]s, splitting
199	/// each raw message on its first blank line into `summary`/`body` --
200	/// mirroring how `gix`'s own commit-message parsing (used by
201	/// `GitRepository::commits_since_with_pathspec`) splits title from body,
202	/// so both backends hand callers the same shape.
203	fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
204	    let mut commits = Vec::new();
205	
206	    for record in stdout.split(RECORD_SEP) {
207	        // `tformat:`-style `--format=` output (the default when the format
208	        // string doesn't start with `format:`/`tformat:`) appends a
209	        // trailing newline after every entry; strip it rather than the
210	        // message's own content.
211	        let record = record.trim_end_matches('\n');
212	        if record.is_empty() {
213	            continue;
214	        }
215	
216	        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
217	            return Err(VcsError::Git(format!(
218	                "could not parse `git log` output in `{}` into commit records: expected a \
219	                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
220	                cwd.display()
221	            )));
222	        };
223	
224	        let sha = CommitSha::parse(sha_str).map_err(|e| {
225	            VcsError::Git(format!(
226	                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
227	                cwd.display()
228	            ))
229	        })?;
230	
231	        let message = message.replace("\r\n", "\n");
232	        let (summary, body) = match message.split_once("\n\n") {
233	            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
234	            None => (message.trim_end().to_string(), None),
235	        };
236	
237	        commits.push(GitCommit { sha, summary, body });
238	    }
239	
240	    Ok(commits)
241	}
