228	        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
229	        let letter = pep440_prerelease_letter(tag);
230	
231	        let mut counter = 0u64;
232	        let current_raw = current.render();
233	        if let Some(rest) = current_raw.strip_prefix(release_str) {
234	            let num_str = match letter {
235	                Some(letter) => rest.strip_prefix(letter),
236	                None => rest.strip_prefix(".dev"),
237	            };
238	            if let Some(num_str) = num_str {
239	                if let Ok(num) = num_str.parse::<u64>() {
240	                    counter = num + 1;
241	                }
242	            }
243	        }
244	
245	        let prerelease_str = match letter {
246	            Some(letter) => format!("{release_str}{letter}{counter}"),
247	            None => format!("{release_str}.dev{counter}"),
248	        };
