38	impl Version {
39	    pub fn parse(raw: &str, grammar: VersionGrammar) -> Result<Self, VersionParseError> {
40	        match grammar {
41	            VersionGrammar::SemVer => {
42	                let parsed = semver::Version::parse(raw).map_err(|e| VersionParseError {
43	                    raw: raw.to_string(),
44	                    grammar,
45	                    message: e.to_string(),
46	                })?;
47	                Ok(Version {
48	                    grammar,
49	                    raw: raw.to_string(),
50	                    parsed: ParsedVersion::SemVer(parsed),
51	                })
52	            }
53	            VersionGrammar::Pep440 => {
54	                let parsed = raw
55	                    .parse::<pep440_rs::Version>()
56	                    .map_err(|e| VersionParseError {
57	                        raw: raw.to_string(),
58	                        grammar,
59	                        message: e.to_string(),
60	                    })?;
61	                // PEP 440 defines multiple equivalent spellings for the same
62	                // version (e.g. `1.0.0-alpha1`, `1.0.0_alpha1`, `1.0.0a1`).
63	                // Normalize `raw` to pep440_rs's canonical rendering so that
64	                // logically-equal inputs produce identical `raw` values, and
65	                // therefore compare `==` and hash equal (derived PartialEq/Eq/
66	                // Hash include `raw`). SemVer has no analogous normalization
67	                // requirement (each version already has one canonical form),
68	                // so the caller's literal input is preserved for that grammar.
69	                let canonical = parsed.to_string();
70	                Ok(Version {
71	                    grammar,
72	                    raw: canonical,
73	                    parsed: ParsedVersion::Pep440(parsed),
74	                })
75	            }
76	            VersionGrammar::Maven => Err(VersionParseError {
77	                raw: raw.to_string(),
78	                grammar,
79	                message: format!("{grammar:?} has no versioning implementation yet (§7.7)"),
80	            }),
81	        }
82	    }
83	
84	    pub fn semver(major: u64, minor: u64, patch: u64) -> Self {
85	        let parsed = semver::Version::new(major, minor, patch);
86	        Version {
87	            grammar: VersionGrammar::SemVer,
88	            raw: parsed.to_string(),
89	            parsed: ParsedVersion::SemVer(parsed),
90	        }
91	    }
92	
93	    pub fn grammar(&self) -> VersionGrammar {
94	        self.grammar
95	    }
96	
97	    pub fn render(&self) -> &str {
98	        &self.raw
99	    }
100	
101	    pub fn raw(&self) -> &str {
102	        &self.raw
103	    }
104	
105	    pub fn major(&self) -> Option<u64> {
106	        match &self.parsed {
107	            ParsedVersion::SemVer(v) => Some(v.major),
108	            ParsedVersion::Pep440(v) => v.release().first().copied(),
109	        }
110	    }
111	
112	    pub fn minor(&self) -> Option<u64> {
113	        match &self.parsed {
114	            ParsedVersion::SemVer(v) => Some(v.minor),
115	            ParsedVersion::Pep440(v) => v.release().get(1).copied(),
116	        }
117	    }
118	
119	    pub fn patch(&self) -> Option<u64> {
120	        match &self.parsed {
121	            ParsedVersion::SemVer(v) => Some(v.patch),
122	            ParsedVersion::Pep440(v) => v.release().get(2).copied(),
123	        }
124	    }
125	
126	    pub fn is_prerelease(&self) -> bool {
127	        match &self.parsed {
128	            ParsedVersion::SemVer(v) => !v.pre.is_empty(),
129	            ParsedVersion::Pep440(v) => v.is_pre() || v.is_dev(),
130	        }
131	    }
132	
133	    pub fn compare(&self, other: &Version) -> Result<std::cmp::Ordering, GrammarMismatch> {
134	        if self.grammar != other.grammar {
135	            return Err(GrammarMismatch {
136	                left: self.grammar,
137	                right: other.grammar,
138	            });
139	        }
140	        match (&self.parsed, &other.parsed) {
141	            (ParsedVersion::SemVer(a), ParsedVersion::SemVer(b)) => Ok(a.cmp(b)),
142	            (ParsedVersion::Pep440(a), ParsedVersion::Pep440(b)) => Ok(a.cmp(b)),
143	            _ => unreachable!(),
144	        }
145	    }
146	
147	    pub fn partial_compare(&self, other: &Version) -> Option<std::cmp::Ordering> {
148	        self.compare(other).ok()
149	    }
150	}
