167	impl<'de> Deserialize<'de> for Version {
168	    /// Generic (grammar-unaware) deserialization. The serialized form of a
169	    /// `Version` is just its raw string (see `Serialize`), which does not
170	    /// carry the grammar it was parsed under, so this impl cannot *know*
171	    /// which grammar to use — it can only guess by trying grammars in turn,
172	    /// exactly as `VersionReq::deserialize` already does for Cargo/Npm/Pypi.
173	    ///
174	    /// SemVer is tried first because it is the strictest, most unambiguous
175	    /// grammar; PEP 440 is tried only if SemVer parsing fails. This means a
176	    /// string that happens to be valid under *both* grammars (e.g. plain
177	    /// `1.2.3`) always resolves to `VersionGrammar::SemVer`, never
178	    /// `VersionGrammar::Pep440` — the same residual-ambiguity tradeoff
179	    /// `VersionReq::deserialize` accepts for its Cargo/Npm/Pypi chain.
180	    ///
181	    /// Callers that know the intended ecosystem/grammar ahead of time (e.g.
182	    /// because a sibling field names it, or the value came from a
183	    /// known-SemVer-only source such as a git tag) should prefer
184	    /// [`Version::parse`] with an explicit [`VersionGrammar`] instead of
185	    /// going through this generic `serde` impl.
186	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
187	    where
188	        D: Deserializer<'de>,
189	    {
190	        let s = String::deserialize(deserializer)?;
191	        Version::parse(&s, VersionGrammar::SemVer)
192	            .or_else(|_| Version::parse(&s, VersionGrammar::Pep440))
193	            .map_err(serde::de::Error::custom)
194	    }
195	}
