17	/// Publishes every package in the workspace's publish plan to its ecosystem
18	/// registry (crates.io, npm, PyPI) by shelling out to that ecosystem's own
19	/// publisher CLI (`cargo publish`, `npm publish`, `twine upload`) — never by
20	/// talking to a registry's HTTP API directly.
21	///
22	/// Respects the global `--dry-run` flag: when set, this only computes and
23	/// prints the plan that WOULD be published (the same plan `plan-publish`
24	/// reports) and returns without constructing a [`PublishOrchestrator`] or
25	/// running any publisher command.
26	pub fn handle(_args: PublishArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
27	    let runner = CliCommandRunner;
28	    let ws = load_workspace(global, &runner)?;
29	
30	    let opts = PublishOptions::default();
31	    let plan = plan_publish(&ws, &opts)?;
32	
33	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
34	        match global.format {
35	            OutputFormat::Json => write_json(&mut std::io::stdout(), &plan)?,
36	            OutputFormat::Text => {
37	                println!(
38	                    "Dry run: about to publish the following plan (nothing will be published):"
39	                );
40	                render::render_publish(&plan, &mut std::io::stdout())?;
41	            }
42	        }
43	        return Ok(ExitCode::SUCCESS);
44	    };
45	
46	    let client = SubprocessRegistryClient::new(CliCommandRunner, ws.root.clone());
47	    let orchestrator = PublishOrchestrator::new(client, AlwaysRetryPolicy, SystemTimeProvider);
48	    let report = orchestrator.execute(&plan, &permit);
49	
50	    match global.format {
51	        OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
52	        OutputFormat::Text => render::render_publish_report(&report, &mut std::io::stdout())?,
53	    }
54	
55	    if report.has_failures() {
56	        return Ok(ExitCode::FAILURE);
57	    }
58	
59	    Ok(ExitCode::SUCCESS)
60	}
