//! Track 0 spike: does gix low-level plumbing read a real git repo from inside
//! a WASM guest via WASI filesystem preopens?
//!
//! Compile:
//!   cargo rustc --example gix_wasm_spike -p callisto-moon \
//!     --target wasm32-wasip1 --features gix-spike
//!
//! Run (from the workspace root, which is a git repo):
//!   wasmtime run --dir . \
//!     -- target/wasm32-wasip1/debug/examples/gix_wasm_spike.wasm
//!
//! Expected outcome A (spike succeeds): exits 0, prints HEAD SHA and commit kind.
//! Expected outcome B (spike fails): exits 1, prints the error and the system-call
//!   or WASI restriction that broke it.  The error message is the finding.
//!
//! This binary is deliberately NOT part of the shipped wasm artifact; it exists
//! only to answer the go/no-go question for Track C's exec-seam design choice.

#![cfg(feature = "gix-spike")]

use gix_odb::HeaderExt as _;

fn main() {
    if let Err(e) = run() {
        eprintln!("SPIKE FAIL: {e}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), Box<dyn std::error::Error>> {
    // Under WASI, current_dir() returns "/" unless the host preopen maps "."
    // to a real directory.  wasmtime --dir . maps "." → workspace root.
    let cwd = std::env::current_dir()?;
    println!("cwd: {}", cwd.display());

    let git_dir = cwd.join(".git");
    println!(".git exists: {}", git_dir.exists());

    // ── Step 1: open the loose-object + pack-file store via gix-odb ──────────
    let objects_dir = git_dir.join("objects");
    println!("objects dir exists: {}", objects_dir.exists());

    let odb = gix_odb::at(&objects_dir)?;
    println!("gix-odb Handle opened OK");

    // ── Step 2: read HEAD via gix-ref ─────────────────────────────────────────
    // `gix_ref::file::Store::at` opens the ref store rooted at `.git/`.
    let ref_store = gix_ref::file::Store::at(
        git_dir.clone(),
        gix_ref::store::init::Options {
            object_hash: gix_hash::Kind::Sha1,
            ..Default::default()
        },
    )?;
    println!("gix-ref Store opened OK");

    // Find HEAD and peel to its final target object id.
    let head_ref = ref_store.find("HEAD")?;
    let head_target = head_ref.target;
    println!("HEAD target kind: {}", if matches!(head_target, gix_ref::Target::Object(_)) { "direct" } else { "symbolic" });

    // If HEAD is symbolic (e.g. ref: refs/heads/main), follow it one hop.
    let head_id = match head_target {
        gix_ref::Target::Object(id) => id,
        gix_ref::Target::Symbolic(name) => {
            let resolved = ref_store.find(name.as_bstr())?;
            resolved
                .target
                .try_id()
                .ok_or("symbolic ref did not resolve to an oid")?
                .to_owned()
        }
    };
    println!("HEAD SHA: {head_id}");

    // ── Step 3: read the commit object header ─────────────────────────────────
    let header = odb.header(head_id.as_ref())?;
    println!(
        "HEAD object: kind={:?} size={}",
        header.kind(),
        header.size()
    );

    println!("SPIKE SUCCESS: gix plumbing reads work under WASI");
    Ok(())
}

