export const meta = {
  name: 'callisto-proof-audit',
  description: 'Full proof audit of the Callisto Rust workspace — bugs, performance, security, architecture',
  phases: [
    { title: 'Recon', detail: 'Build live/dead file manifest from entry points' },
    { title: 'Scan', detail: 'Apply Rust hazard taxonomies across live files' },
    { title: 'Adversary', detail: 'Confirm or refute each candidate by reading actual code' },
  ],
}

const WORKSPACE = '/Users/gabe/Projects/callisto'

// Phase 1 — Recon
phase('Recon')
const recon = await agent(
  `You are proof-recon. Workspace root: ${WORKSPACE}

Build the proof manifest:
1. Detect language (Cargo.toml present → rust)
2. Identify entry points: binary crates (src/main.rs or [[bin]] in Cargo.toml), lib.rs roots
3. Trace imports and mod declarations from each entry point to build the live file set
4. Classify remaining workspace files as dead
5. List all live_files with their full paths

Return a JSON manifest with: workspace_root, language, entry_points, live_files (array of absolute paths), dead_files (array), confidence (high/medium/low), reasoning`,
  { label: 'proof-recon', agentType: 'proof:proof-recon', schema: {
    type: 'object',
    properties: {
      workspace_root: { type: 'string' },
      language: { type: 'string' },
      entry_points: { type: 'array', items: { type: 'string' } },
      live_files: { type: 'array', items: { type: 'string' } },
      dead_files: { type: 'array', items: { type: 'string' } },
      confidence: { type: 'string' },
      reasoning: { type: 'string' },
    },
    required: ['workspace_root', 'language', 'entry_points', 'live_files', 'dead_files', 'confidence'],
  }}
)

log(`Recon complete: ${recon.live_files.length} live files, ${recon.dead_files.length} dead files, confidence: ${recon.confidence}`)

// Phase 2 — Scan (parallel across hazard categories)
phase('Scan')

const HAZARD_CATEGORIES = [
  'error-handling: unwrap/expect in lib code, silent error swallowing, missing ? propagation, lossy error conversions',
  'memory-safety: unsafe blocks, raw pointer arithmetic, uninitialized memory, slice index panics, integer overflow in release mode',
  'concurrency: data races, lock ordering, deadlocks, shared mutable state across threads, Arc<Mutex> misuse',
  'io-and-filesystem: TOCTOU races, path traversal, atomic write failures, missing fsync, directory traversal',
  'correctness: off-by-one errors, wrong comparisons, incorrect algorithm logic, missing edge cases in core domain logic',
  'performance: redundant allocations, O(n^2) in hot paths, unnecessary clones, repeated manifest reads, HashMap vs BTreeMap ordering',
  'security: command injection in shell-out code, hardcoded secrets, insufficient input validation at trust boundaries',
  'architecture: layer isolation violations (AGPL crates depended on by MIT crates), dead code paths, unreachable match arms',
]

const scanResults = await parallel(HAZARD_CATEGORIES.map(category => () =>
  agent(
    `You are proof-scanner. Workspace: ${WORKSPACE}. Language: rust.

Recon manifest (live files only — do NOT scan dead files):
Live files: ${recon.live_files.slice(0, 80).join('\n')}
${recon.live_files.length > 80 ? `...and ${recon.live_files.length - 80} more` : ''}

Hazard category to scan: ${category}

Read the source files and apply hazard patterns for this category. For each pattern match, read surrounding code to assess plausibility before emitting a candidate. Dead files are never scanned.

Return JSON with hazard_category and candidates array. Each candidate: id, description, file, line, severity (critical/high/medium/low), trigger_condition, search_pattern.`,
    { label: `scan:${category.split(':')[0]}`, phase: 'Scan', agentType: 'proof:proof-scanner', schema: {
      type: 'object',
      properties: {
        hazard_category: { type: 'string' },
        candidates: { type: 'array', items: {
          type: 'object',
          properties: {
            id: { type: 'string' },
            description: { type: 'string' },
            file: { type: 'string' },
            line: { type: 'number' },
            severity: { type: 'string' },
            trigger_condition: { type: 'string' },
            search_pattern: { type: 'string' },
          },
          required: ['id', 'description', 'file', 'line', 'severity', 'trigger_condition'],
        }}
      },
      required: ['hazard_category', 'candidates'],
    }}
  )
))

const allCandidates = scanResults.filter(Boolean).flatMap(r => r.candidates)
log(`Scan complete: ${allCandidates.length} candidates across ${scanResults.filter(Boolean).length} hazard categories`)

// Phase 3 — Adversary (confirm or refute each candidate)
phase('Adversary')

const adversaryResults = await parallel(allCandidates.map(candidate => () =>
  agent(
    `You are proof-adversary. Workspace: ${WORKSPACE}.

Candidate finding to evaluate:
${JSON.stringify(candidate, null, 2)}

Recon manifest context:
- Live files: ${recon.live_files.length} files
- Language: rust

Your job: attempt to REFUTE this candidate. Read the actual file at the reported location. Trace control flow from the trigger condition. Look for:
- Validation guards or early returns that prevent the bug
- Type constraints that make the trigger impossible
- Caller-side preconditions
- Test coverage that proves correct behavior

Default assumption: REFUTED. Only confirm if no valid refutation can be constructed AND:
1. The trigger is reachable in live code
2. No guard prevents the bad path  
3. There is an identifiable root cause

Return JSON: confirmed (boolean), finding (the candidate object if confirmed, with updated description), refutation_reason (if not confirmed).`,
    { label: `adversary:${candidate.id}`, phase: 'Adversary', schema: {
      type: 'object',
      properties: {
        confirmed: { type: 'boolean' },
        finding: { type: 'object' },
        refutation_reason: { type: 'string' },
      },
      required: ['confirmed'],
    }}
  )
))

const confirmedFindings = adversaryResults
  .filter(Boolean)
  .filter(r => r.confirmed && r.finding)
  .map(r => r.finding)

log(`Adversary complete: ${confirmedFindings.length} confirmed / ${allCandidates.length - confirmedFindings.length} refuted`)

return {
  recon,
  total_candidates: allCandidates.length,
  confirmed_findings: confirmedFindings,
  finding_report: {
    schema: 'finding-report@1',
    workspace: WORKSPACE,
    language: recon.language,
    findings: confirmedFindings,
    summary: `${confirmedFindings.length} confirmed findings from ${allCandidates.length} candidates across ${HAZARD_CATEGORIES.length} hazard categories`,
  }
}

