229	    // moon's real `InitializeExtensionInput` (= `InitializePluginInput`) only
230	    // carries `context: MoonContext` — there is no `confirmed`/`yes` flag in
231	    // the real protocol (that was a callisto-only field on the old, locally
232	    // invented type). `InitOptions.yes` now gates `init`'s reconcile-apply
233	    // path (docs/00-design.md §18 Q5.4 mechanism 1): on a first run it has
234	    // no effect (scaffolding an absent `callisto.toml` is always a direct
235	    // write), and on a re-run it decides whether detected drift (e.g. a
236	    // newly-appeared ecosystem) is written or only reported. There is no
237	    // host-side prompt surface here to relay a diff through, so defaulting
238	    // to `true` — auto-applying reconcile drift — is the closest behavior-
239	    // preserving choice to the old unconditional-write behavior.
240	    let root = input.context.workspace_root.to_path_buf();
241	    let runner = crate::runner::MoonCommandRunner;
242	    let locator = crate::locator::MoonProjectLocator::new(&runner, root.clone())?;
243	    let ws = callisto_graph::Workspace::load(root, &locator, &runner)
244	        .map_err(|e| LocateError::Graph(Box::new(e)))?;
245	    let opts = InitOptions { yes: true };
246	
247	    // Run callisto's existing init-detection/scaffolding logic. moon's real
248	    // `InitializeExtensionOutput` (= `InitializePluginOutput`) has no field
249	    // that can carry an arbitrary `InitReport` (schema version, config path,
250	    // diagnostics) — its shape is specifically for describing settings to
251	    // inject into moon's own toolchain config and prompts to ask the user,
252	    // neither of which callisto's `InitReport` maps onto cleanly. We still
253	    // run `init` for its side effects (scaffolding `callisto.toml` /
254	    // `.changeset`) and to propagate any error, but intentionally discard
255	    // the returned `InitReport` rather than inventing new output fields
256	    // moon doesn't expect. All fields below are therefore sensible defaults:
257	    // callisto has no hosted config/docs URL to advertise, no moon toolchain
258	    // settings to pre-populate, and no interactive prompts to ask.
259	    // This host surface has no `--dry-run` equivalent -- a moon extension
260	    // initialization is always a real scaffolding write -- so the permit is
261	    // granted unconditionally here rather than derived from a user flag. It
262	    // still goes through the one sanctioned constructor.
263	    let permit = callisto_model::ApplyPermit::granted_unless_dry_run(false);
