11	pub struct MoonProjectLocator<'a, R: CommandRunner> {
12	    runner: &'a R,
13	    workspace_root: PathBuf,
14	    identity: IdentityResolver,
15	    graph: OnceLock<MoonProjectGraph>,
16	}
