18	impl<'a, R: CommandRunner> MoonProjectLocator<'a, R> {
19	    pub fn new(runner: &'a R, workspace_root: PathBuf) -> Result<Self, LocateError> {
20	        let identity =
21	            IdentityResolver::new(&workspace_root).map_err(|e| LocateError::Graph(Box::new(e)))?;
22	        Ok(Self {
23	            runner,
24	            workspace_root,
25	            identity,
26	            graph: OnceLock::new(),
27	        })
28	    }
29	
30	    fn load_graph(&self) -> Result<&MoonProjectGraph, LocateError> {
31	        if let Some(g) = self.graph.get() {
32	            return Ok(g);
33	        }
34	
35	        let out = self
36	            .runner
37	            .run("moon", &["project-graph", "--json"], &self.workspace_root)
38	            .map_err(|_err| LocateError::MoonUnavailable)?;
39	
40	        if out.exit_code != Some(0) {
41	            return Err(LocateError::MoonUnavailable);
42	        }
43	
44	        let graph: MoonProjectGraph =
45	            serde_json::from_str(&out.stdout).map_err(|e| LocateError::MoonOutputParse {
46	                message: e.to_string(),
47	            })?;
48	
49	        let _res = self.graph.set(graph);
50	        Ok(self.graph.get().unwrap())
51	    }
52	
53	    fn resolve_id(&self, root: &Path, eco: Ecosystem) -> Result<PackageId, LocateError> {
54	        self.identity
55	            .resolve(root, eco)
56	            .map_err(|e| LocateError::Graph(Box::new(e)))
57	    }
58	}
