100	impl<'a, R: CommandRunner> ProjectLocator for MoonProjectLocator<'a, R> {
101	    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
102	        let graph = self.load_graph()?;
103	        let mut roots = Vec::new();
104	
105	        for project in &graph.projects {
106	            let abs_path = if project.root.is_absolute() {
107	                project.root.clone()
108	            } else {
109	                self.workspace_root.join(&project.root)
110	            };
111	
112	            if !abs_path.starts_with(&self.workspace_root) {
113	                return Err(LocateError::OutsideWorkspaceRoot {
114	                    path: abs_path,
115	                    root: self.workspace_root.clone(),
116	                });
117	            }
118	
119	            let has_cargo = abs_path.join("Cargo.toml").exists();
120	            let has_npm = abs_path.join("package.json").exists();
121	            let has_pypi = abs_path.join("pyproject.toml").exists();
122	
123	            if has_cargo {
124	                let id = self.resolve_id(&abs_path, Ecosystem::Cargo)?;
125	                roots.push(ProjectRoot {
126	                    id,
127	                    path: project.root.clone(),
128	                    ecosystem: Ecosystem::Cargo,
129	                });
130	            }
131	            if has_npm {
132	                let id = self.resolve_id(&abs_path, Ecosystem::Npm)?;
133	                roots.push(ProjectRoot {
134	                    id,
135	                    path: project.root.clone(),
136	                    ecosystem: Ecosystem::Npm,
137	                });
138	            }
139	            if has_pypi {
140	                let id = self.resolve_id(&abs_path, Ecosystem::Pypi)?;
141	                roots.push(ProjectRoot {
142	                    id,
143	                    path: project.root.clone(),
144	                    ecosystem: Ecosystem::Pypi,
145	                });
146	            }
147	        }
148	
149	        Ok(roots)
150	    }
151	
152	    fn declared_edges(&self) -> Option<Vec<DeclaredEdge>> {
153	        let graph = self.load_graph().ok()?;
154	        let mut edges = Vec::new();
155	
156	        for project in &graph.projects {
157	            let abs_from = if project.root.is_absolute() {
158	                project.root.clone()
159	            } else {
160	                self.workspace_root.join(&project.root)
161	            };
162	
163	            for dep in &project.depends_on {
164	                let abs_to = if dep.project_root.is_absolute() {
165	                    dep.project_root.clone()
166	                } else {
167	                    self.workspace_root.join(&dep.project_root)
168	                };
169	
170	                let from_eco = if abs_from.join("Cargo.toml").exists() {
171	                    Ecosystem::Cargo
172	                } else if abs_from.join("package.json").exists() {
173	                    Ecosystem::Npm
174	                } else if abs_from.join("pyproject.toml").exists() {
175	                    Ecosystem::Pypi
176	                } else {
177	                    continue;
178	                };
179	
180	                let to_eco = if abs_to.join("Cargo.toml").exists() {
181	                    Ecosystem::Cargo
182	                } else if abs_to.join("package.json").exists() {
183	                    Ecosystem::Npm
184	                } else if abs_to.join("pyproject.toml").exists() {
185	                    Ecosystem::Pypi
186	                } else {
187	                    continue;
188	                };
189	
190	                if let (Ok(from), Ok(to)) = (
191	                    self.resolve_id(&abs_from, from_eco),
192	                    self.resolve_id(&abs_to, to_eco),
193	                ) {
194	                    edges.push(DeclaredEdge {
195	                        from,
196	                        to,
197	                        kind: scope_to_declared_edge_kind(dep.scope),
198	                        via: dep.via.clone(),
199	                    });
200	                }
201	            }
202	        }
203	
204	        Some(edges)
205	    }
206	}
