214	impl VersionReq {
215	    pub fn parse(raw: &str, ecosystem: Ecosystem) -> Result<Self, VersionParseError> {
216	        let grammar = ecosystem.version_grammar();
217	        match grammar {
218	            VersionGrammar::SemVer => {
219	                let req = semver::VersionReq::parse(raw).map_err(|e| VersionParseError {
220	                    raw: raw.to_string(),
221	                    grammar,
222	                    message: e.to_string(),
223	                })?;
224	                Ok(VersionReq {
225	                    grammar,
226	                    ecosystem,
227	                    req: ParsedVersionReq::SemVer(req),
228	                    raw: raw.to_string(),
229	                })
230	            }
231	            VersionGrammar::Pep440 => {
232	                let req =
233	                    raw.parse::<pep440_rs::VersionSpecifiers>()
234	                        .map_err(|e| VersionParseError {
235	                            raw: raw.to_string(),
236	                            grammar,
237	                            message: e.to_string(),
238	                        })?;
239	                Ok(VersionReq {
240	                    grammar,
241	                    ecosystem,
242	                    req: ParsedVersionReq::Pep440(req),
243	                    raw: raw.to_string(),
244	                })
245	            }
246	            VersionGrammar::Maven => Err(VersionParseError {
247	                raw: raw.to_string(),
248	                grammar,
249	                message: format!("{grammar:?} version requirements not implemented"),
250	            }),
251	        }
252	    }
