290	    /// scoping for severity inference, where a merge commit's message
291	    /// duplicates work already represented by its non-merge ancestors.
292	    pub fn commits_since_with_pathspec(
293	        &self,
294	        since: Option<&CommitSha>,
295	        pathspecs: &[PathBuf],
296	    ) -> Result<Vec<GitCommit>, VcsError> {
297	        #[cfg(not(target_arch = "wasm32"))]
298	        {
299	            let head = self
300	                .repo
301	                .head_commit()
302	                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
303	
304	            let revwalk = self
305	                .repo
306	                .rev_walk(vec![head.id])
307	                .all()
308	                .map_err(|e| VcsError::Git(format!("Failed to create revwalk: {e}")))?;
309	
310	            let stop_hex = since.map(|s| s.as_str().to_string());
311	
312	            let mut commits = Vec::new();
313	            for info in revwalk {
314	                let info = info.map_err(|e| VcsError::Git(e.to_string()))?;
315	                let hex = info.id.to_hex().to_string();
316	
317	                if let Some(ref target) = stop_hex {
318	                    if &hex == target {
319	                        break;
320	                    }
321	                }
322	
323	                if info.parent_ids().count() > 1 {
324	                    continue;
325	                }
326	
327	                let commit_obj = info
328	                    .object()
329	                    .map_err(|e| VcsError::Git(format!("Failed to load commit object: {e}")))?;
330	
331	                if !pathspecs.is_empty() {
332	                    let touched =
333	                        commit_touches_pathspecs(&self.repo, &info, &commit_obj, pathspecs)?;
334	                    if !touched {
335	                        continue;
336	                    }
337	                }
338	
339	                let sha = CommitSha::parse(&hex)
340	                    .map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;
341	
342	                let message = commit_obj
343	                    .message()
344	                    .map_err(|e| VcsError::Git(e.to_string()))?;
345	                let summary = message
346	                    .title
347	                    .to_string()
348	                    .replace("\r\n", "\n")
349	                    .trim_end()
350	                    .to_string();
351	                let body = message.body.map(|b| b.to_string().replace("\r\n", "\n"));
352	
353	                commits.push(GitCommit { sha, summary, body });
354	            }
355	
356	            Ok(commits)
357	        }
358	        #[cfg(target_arch = "wasm32")]
359	        {
360	            let _unused = (since, pathspecs);
361	            Ok(Vec::new())
362	        }
363	    }
