            if has_npm {
                let id = self.resolve_id(&abs_path, Ecosystem::Npm)?;
                roots.push(ProjectRoot {
                    id,
                    path: rel_path.clone(),
                    ecosystem: Ecosystem::Npm,
                });
            }
            if has_pypi {
                let id = self.resolve_id(&abs_path, Ecosystem::Pypi)?;
                roots.push(ProjectRoot {
                    id,
                    path: rel_path,
                    ecosystem: Ecosystem::Pypi,
                });
            }
        }

        Ok(roots)
    }

