export const meta = {
  name: 'callisto-audit',
  description: 'Full architectural and code evaluation of the Callisto codebase',
  phases: [
    { title: 'Scan', detail: 'Parallel sweep across 7 crate areas' },
    { title: 'Synthesize', detail: 'Combine and prioritize findings into a track-based plan' },
  ],
}

const FINDING_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          file: { type: 'string' },
          lines: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          category: { type: 'string' },
          title: { type: 'string' },
          description: { type: 'string' },
          recommendation: { type: 'string' },
        },
        required: ['id', 'file', 'severity', 'category', 'title', 'description', 'recommendation'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['findings', 'summary'],
}

const AREAS = [
  {
    key: 'model-format',
    label: 'callisto-model + callisto-format',
    prompt: 'You are an adversarial code reviewer. Read EVERY file in /Users/gabe/Projects/callisto/crates/callisto-model/src/ and /Users/gabe/Projects/callisto/crates/callisto-format/src/. Also skim /Users/gabe/Projects/callisto/docs/03-polyglot-spec.md and docs/04-python-engine-spec.md for spec context.\n\nEvaluate for ALL of:\n\n1. BUGS: wrong version comparison/ordering (SemVer, PEP 440, npm), incorrect bump logic, panics on edge-case inputs, HashSet where BTreeSet is needed for determinism, PartialEq/Hash inconsistency on map-key types, missing post+dev guards\n2. PERFORMANCE: unnecessary clone() calls, redundant parsing of the same string twice, allocations in hot paths\n3. SPEC GAPS: things docs say are supported but have no implementation (PEP 735 groups, epoch versions, missing ecosystem match arms)\n4. MISSING EDGE CASES: inputs causing silent wrong results instead of errors, missing validation at public API boundaries\n5. ERROR HANDLING: .unwrap() in non-test library code, missing error variants\n6. CODE ORGANIZATION: functions >60 lines that need splitting, files >400 lines, logic in wrong layer (formatting in model layer), pub API exposing implementation details, dead code\n7. BEST PRACTICES: missing derives, inconsistent naming, missing doc comments on public items\n\nFor each finding give: file path (relative to repo root), approximate line range, severity (critical/high/medium/low), category, title, description, recommendation. Produce at least 10 findings. Return JSON.'
  },
  {
    key: 'manifests',
    label: 'callisto-manifests',
    prompt: 'You are an adversarial code reviewer. Read ALL files in /Users/gabe/Projects/callisto/crates/callisto-manifests/src/ (cargo.rs ~1150 lines, npm.rs ~999 lines, python.rs ~1002 lines, atomic.rs, lib.rs, and any others). Also read /Users/gabe/Projects/callisto/crates/callisto-changelog/src/ to check if it still has its own atomic_write copy. Skim docs/03-polyglot-spec.md and docs/04-python-engine-spec.md.\n\nEvaluate for ALL of:\n\n1. BUGS: CST mutation bugs (toml_edit/serde_json divergence from disk), BOM/CRLF/indentation fingerprint - is handling consistent across all three editors (npm.rs has LineEnding+has_bom fingerprint - do cargo.rs and python.rs match?), validate-before-mutate discipline - does any mutation path touch the doc before confirming the target section exists, round_trip() correctness for edge cases (pre-release markers, wildcards, Python "~="), atomic_write usage consistency\n2. PERFORMANCE: manifests re-read when already open, O(n^2) dependency walks\n3. SPEC GAPS: PEP 508 constraint rewriting (spec claims support - is it implemented?), PEP 735 dependency groups, npm overrides/resolutions field coverage, Cargo workspace inheritance (workspace.dependencies)\n4. MISSING EDGE CASES: empty dependency sections, packages with no version field, Unicode package names\n5. ERROR HANDLING: .unwrap() in non-test code, missing error variants\n6. CODE ORGANIZATION: all three files are ~1000 lines - identify natural split points, shared logic that could be extracted to a common module, functions >60 lines\n\nProduce at least 12 findings. Return JSON.'
