phase('Scan')
log('Launching 7 parallel scan agents...')

const scanResults = await parallel(
  AREAS.map(function(area) {
    return function() {
      return agent(area.prompt, {
        label: 'scan:' + area.key,
        phase: 'Scan',
        schema: FINDING_SCHEMA,
        effort: 'high',
      })
    }
  })
)

const validResults = scanResults.filter(Boolean)
log('Scan complete: ' + validResults.length + '/7 agents returned findings')

const allFindings = validResults.flatMap(function(r, i) {
  return (r.findings || []).map(function(f) {
    return Object.assign({}, f, { area: AREAS[i] ? AREAS[i].key : 'unknown' })
  })
})

log('Total raw findings: ' + allFindings.length)

phase('Synthesize')
log('Synthesizing findings into prioritized plan...')

const PLAN_SCHEMA = {
  type: 'object',
  properties: {
    executive_summary: { type: 'string' },
    critical_bugs: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          detail: { type: 'string' },
          files: { type: 'string' },
        },
        required: ['title', 'detail', 'files'],
      },
    },
    tracks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          name: { type: 'string' },
          priority: { type: 'string', enum: ['P0', 'P1', 'P2', 'P3'] },
          effort: { type: 'string', enum: ['small', 'medium', 'large', 'xlarge'] },
          description: { type: 'string' },
          findings: { type: 'array', items: { type: 'string' } },
          files_affected: { type: 'array', items: { type: 'string' } },
          recommended_agent_type: { type: 'string' },
          recommended_model: { type: 'string' },
          tdd_required: { type: 'boolean' },
          estimated_tokens: { type: 'string' },
        },
        required: ['id', 'name', 'priority', 'effort', 'description', 'findings', 'files_affected', 'recommended_agent_type', 'tdd_required'],
      },
    },
    deferred: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          reason: { type: 'string' },
        },
        required: ['title', 'reason'],
      },
    },
    token_cost_notes: { type: 'string' },
  },
  required: ['executive_summary', 'critical_bugs', 'tracks', 'deferred', 'token_cost_notes'],
}

const synthesisInput = JSON.stringify(allFindings)

const plan = await agent(
  'You are the lead architect synthesizing a full code audit of the Callisto Rust codebase. Here are all findings from 7 parallel scan agents: ' + synthesisInput + '\n\nYour job:\n1. Deduplicate overlapping findings across agents\n2. Verify severity - downgrade anything scary but actually benign\n3. Identify CRITICAL BUGS (wrong releases, corrupt manifests, silent failures on real inputs)\n4. Group into implementation tracks where: each track has disjoint files (no two P0/P1 tracks touch the same file simultaneously), tracks ordered P0/P1/P2/P3, each track fits one TDD session (3-4 files max)\n5. Effort: small (<1h), medium (2-4h), large (4-8h), xlarge (multi-day)\n6. Recommend agent type and model: simple refactors -> lambda:lambda-implementer + sonnet; complex logic bugs -> lambda:lambda-implementer + opus; spec compliance -> vector:vector-planner then lambda + opus; architecture -> Plan agent\n7. Deferred: spec decisions needed, too risky to change, Go engine gaps, Python workspace discovery (needs design)\n8. token_cost_notes: rough total token estimate for implementing all tracks (small=100k, medium=200k, large=400k, xlarge=800k) and which tracks have best ROI\n\nBe opinionated. Flag things that will actually bite users. Return complete JSON plan.',
  {
    label: 'synthesize',
    phase: 'Synthesize',
    schema: PLAN_SCHEMA,
    model: 'opus',
    effort: 'high',
  }
)

return { total_findings: allFindings.length, allFindings, plan }

