 40 │ /// Publishes every package in the workspace's publish plan to its ecosystem
 41 │ /// registry (crates.io, npm, PyPI) by shelling out to that ecosystem's own
 42 │ /// publisher CLI (`cargo publish`, `npm publish`, `twine upload`) — never by
 43 │ /// talking to a registry's HTTP API directly.
 44 │ ///
 45 │ /// Respects the global `--dry-run` flag: when set, this only computes and
 46 │ /// prints the plan that WOULD be published (the same plan `plan-publish`
 47 │ /// reports) and returns without constructing a [`PublishOrchestrator`] or
 48 │ /// running any publisher command.
 49 │ pub fn handle(_args: PublishArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 50 │     let runner = CliCommandRunner;
 51 │     let ws = load_workspace(global, &runner)?;
 52 │ 
 53 │     let opts = PublishOptions::default();
 54 │     let plan = plan_publish(&ws, &opts)?;
 55 │ 
 56 │     let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
 57 │         match global.format {
 58 │             OutputFormat::Json => write_json(&mut std::io::stdout(), &plan)?,
 59 │             OutputFormat::Text => write_dry_run_text(&plan, &mut std::io::stdout())?,
 60 │         }
 61 │         return Ok(ExitCode::SUCCESS);
 62 │     };
 63 │ 
 64 │     let client = SubprocessRegistryClient::new(CliCommandRunner, ws.root.clone());
 65 │     let orchestrator = PublishOrchestrator::new(client, AlwaysRetryPolicy, SystemTimeProvider);
 66 │     let report = orchestrator.execute(&plan, &permit);
 67 │ 
 68 │     match global.format {
 69 │         OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
 70 │         OutputFormat::Text => render::render_publish_report(&report, &mut std::io::stdout())?,
 71 │     }
 72 │ 
 73 │     if report.has_failures() {
 74 │         return Ok(ExitCode::FAILURE);
 75 │     }
 76 │ 
 77 │     Ok(ExitCode::SUCCESS)
 78 │ }
