275	    /// Attempts to publish every package in `plan` to its ecosystem
276	    /// registry, recording a per-package outcome (or failure) for each one
277	    /// rather than aborting the whole batch on the first error — one
278	    /// package's registry rejection or auth failure must not silently erase
279	    /// the fact that earlier packages in the same run genuinely published or
280	    /// were already present.
281	    pub fn execute(&self, plan: &PublishPlan, permit: &ApplyPermit) -> PublishReport {
282	        let mut attempts = Vec::new();
283	
284	        for rust_crate in &plan.rust_crates {
285	            let pkg_id = PackageId::Prefixed {
286	                ecosystem: Ecosystem::Cargo,
287	                name: rust_crate.name.clone(),
288	            };
289	            attempts.push(self.attempt_publish(pkg_id, rust_crate.version.clone(), permit));
290	        }
291	
292	        for npm_pkg in &plan.npm_platform_packages {
293	            let pkg_id = PackageId::Prefixed {
294	                ecosystem: Ecosystem::Npm,
295	                name: npm_pkg.name.clone(),
296	            };
297	            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
298	        }
299	
300	        for npm_pkg in &plan.npm_main_packages {
301	            let pkg_id = PackageId::Prefixed {
302	                ecosystem: Ecosystem::Npm,
303	                name: npm_pkg.name.clone(),
304	            };
305	            attempts.push(self.attempt_publish(pkg_id, npm_pkg.version.clone(), permit));
306	        }
307	
308	        for pypi_pkg in &plan.pypi_packages {
309	            let pkg_id = PackageId::Prefixed {
310	                ecosystem: Ecosystem::Pypi,
311	                name: pypi_pkg.name.clone(),
312	            };
313	            attempts.push(self.attempt_publish(pkg_id, pypi_pkg.version.clone(), permit));
314	        }
315	
316	        PublishReport {
317	            schema_version: callisto_model::SCHEMA_VERSION,
318	            attempts,
319	            diagnostics: Vec::new(),
320	        }
321	    }
