323	    fn attempt_publish(
324	        &self,
325	        package: PackageId,
326	        version: Version,
327	        permit: &ApplyPermit,
328	    ) -> PublishAttempt {
329	        let result = match self.publish_with_retry(&package, &version, permit) {
330	            Ok(PublishOutcome::Published) => PublishAttemptResult::Published,
331	            Ok(PublishOutcome::AlreadyPublished) => PublishAttemptResult::AlreadyPublished,
332	            Err(err) => PublishAttemptResult::Failed {
333	                error: err.to_string(),
334	            },
335	        };
336	
337	        PublishAttempt {
338	            package,
339	            version,
340	            result,
341	        }
342	    }
343	
344	    fn publish_with_retry(
345	        &self,
346	        pkg_id: &PackageId,
347	        version: &Version,
348	        permit: &ApplyPermit,
349	    ) -> Result<PublishOutcome, RegistryError> {
350	        if self.client.is_published(pkg_id, version)? {
351	            return Ok(PublishOutcome::AlreadyPublished);
352	        }
353	
354	        loop {
355	            match self.client.publish(pkg_id, version, permit) {
356	                // Both a fresh publish and a publish-time "already there"
357	                // classification are done-and-not-an-error: neither should
358	                // retry, and AlreadyPublished is treated identically to the
359	                // is_published short-circuit above.
360	                Ok(outcome @ (PublishOutcome::Published | PublishOutcome::AlreadyPublished)) => {
361	                    return Ok(outcome)
362	                }
363	                Err(RegistryError::RateLimited(retry_after)) => {
364	                    if retry_after > Duration::from_secs(600) {
365	                        return Err(RegistryError::RateLimited(retry_after));
366	                    }
367	                    self.policy.check_rate_limit(retry_after)?;
368	                    self.time.sleep(retry_after);
369	                }
370	                Err(RegistryError::AuthFailed(err)) => {
371	                    return Err(RegistryError::AuthFailed(err));
372	                }
373	                Err(err) => {
374	                    return Err(err);
375	                }
376	            }
377	        }
378	    }
379	}
