203	    /// ([`Self::npm_publish`]).
204	    fn build_npm_publish_command(
205	        &self,
206	        package_name: &str,
207	        tag: Option<&str>,
208	        access: Option<&str>,
209	    ) -> (String, Vec<String>) {
210	        let mut extra: Vec<String> = Vec::new();
211	        if let Some(t) = tag {
212	            extra.push("--tag".to_string());
213	            extra.push(t.to_string());
214	        }
215	        if let Some(av) = access {
216	            extra.push("--access".to_string());
217	            extra.push(av.to_string());
218	        }
219	
220	        if self.cwd.join("pnpm-lock.yaml").exists() {
221	            let mut args = vec![
222	                "publish".to_string(),
223	                "--filter".to_string(),
224	                package_name.to_string(),
225	            ];
226	            args.extend(extra);
227	            return ("pnpm".to_string(), args);
228	        }
229	
230	        if self.cwd.join("yarn.lock").exists() {
231	            let mut args = vec![
232	                "workspace".to_string(),
233	                package_name.to_string(),
234	                "npm".to_string(),
235	                "publish".to_string(),
236	            ];
237	            args.extend(extra);
238	            return ("yarn".to_string(), args);
239	        }
240	
241	        if self.cwd.join("bun.lockb").exists() {
242	            let mut args = vec!["publish".to_string()];
243	            args.extend(extra);
244	            return ("bun".to_string(), args);
245	        }
246	
247	        // Default: npm
248	        let mut args = vec![
249	            "publish".to_string(),
250	            "--workspace".to_string(),
251	            package_name.to_string(),
252	        ];
253	        args.extend(extra);
254	        ("npm".to_string(), args)
255	    }
