333	                    "--repository-url",
334	                    idx,
335	                    &pattern,
336	                ],
337	            )?
338	        } else {
339	            self.run("twine", &["upload", "--skip-existing", &pattern])?
340	        };
341	        classify_twine_output(&output)
342	    }
