345	impl<R: CommandRunner> RegistryClient for SubprocessRegistryClient<R> {
346	    fn is_published(&self, package: &PackageId, version: &Version) -> Result<bool, RegistryError> {
347	        match package {
348	            PackageId::Prefixed {
349	                ecosystem: Ecosystem::Npm,
350	                ..
351	            } => self.npm_is_published(package, version),
352	
353	            // Cargo: no reliable cargo-CLI-only existence check exists
354	            // (crates.io has no local "is this on the index" subcommand
355	            // short of hitting its HTTP API, which this design deliberately
356	            // avoids). `publish()`'s own AlreadyPublished classification is
357	            // the real source of truth for Cargo.
358	            //
359	            // PyPI: twine's own --skip-existing flag absorbs idempotency at
360	            // upload time, so a pre-check buys nothing extra here either.
361	            PackageId::Prefixed {
362	                ecosystem: Ecosystem::Cargo | Ecosystem::Pypi,
363	                ..
364	            } => Ok(false),
365	
366	            other => Err(RegistryError::Other(format!(
367	                "no subprocess is_published check configured for package identity `{}`",
368	                other.display_name()
369	            ))),
370	        }
371	    }
