373	    fn publish(
374	        &self,
375	        package: &PackageId,
376	        version: &Version,
377	        _permit: &ApplyPermit,
378	    ) -> Result<PublishOutcome, RegistryError> {
379	        match package {
380	            PackageId::Prefixed {
381	                ecosystem: Ecosystem::Cargo,
382	                name,
383	                ..
384	            } => {
385	                let registry = self
386	                    .cargo_registry
387	                    .get(name.as_str())
388	                    .and_then(|r| r.as_deref());
389	                self.cargo_publish(package, registry)
390	            }
391	            PackageId::Prefixed {
392	                ecosystem: Ecosystem::Npm,
393	                name,
394	                ..
395	            } => {
396	                let meta = self.npm_meta.get(name.as_str());
397	                let tag = meta.and_then(|m| m.tag.as_deref());
398	                let access = meta.and_then(|m| m.access.as_ref());
399	                self.npm_publish(package, tag, access)
400	            }
401	            PackageId::Prefixed {
402	                ecosystem: Ecosystem::Pypi,
403	                name,
404	                ..
405	            } => {
406	                let index = self
407	                    .pypi_index
408	                    .get(name.as_str())
409	                    .and_then(|i| i.as_deref());
410	                self.pypi_publish(package, version, index)
411	            }
412	            other => Err(RegistryError::Other(format!(
413	                "no subprocess publisher configured for package identity `{}`",
414	                other.display_name()
