421	
422	fn combined_lower(output: &CommandOutput) -> String {
423	    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
424	}
425	
426	/// Looks for a `retry after <N>` mention in already-lowercased text and
427	/// parses `<N>` as a whole-second duration via the orchestrator's shared
428	/// [`parse_retry_after`] helper.
429	fn extract_retry_after_duration(text_lower: &str) -> Option<Duration> {
430	    const NEEDLE: &str = "retry after ";
431	    let idx = text_lower.find(NEEDLE)?;
432	    let rest = &text_lower[idx + NEEDLE.len()..];
433	    let token = rest.split_whitespace().next()?;
434	    let digits: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
435	    if digits.is_empty() {
436	        return None;
437	    }
438	    parse_retry_after(&digits)
439	}
440	
441	fn detect_rate_limit(text_lower: &str) -> Option<RegistryError> {
442	    if text_lower.contains("429")
443	        || text_lower.contains("too many requests")
444	        || text_lower.contains("rate limit")
445	    {
446	        let dur = extract_retry_after_duration(text_lower).unwrap_or(Duration::from_secs(60));
447	        Some(RegistryError::RateLimited(dur))
448	    } else {
449	        None
450	    }
451	}
452	
453	fn detect_auth_failure(text_lower: &str, raw_stderr: &str) -> Option<RegistryError> {
454	    if text_lower.contains("401")
455	        || text_lower.contains("403")
456	        || text_lower.contains("authentication")
457	        || text_lower.contains("not logged in")
458	        || text_lower.contains("invalid token")
459	        || text_lower.contains("forbidden")
460	    {
461	        Some(RegistryError::AuthFailed(raw_stderr.trim().to_string()))
462	    } else {
463	        None
464	    }
465	}
