467	fn classify_cargo_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
468	    let combined = combined_lower(output);
469	
470	    if combined.contains("already exists") || combined.contains("already uploaded") {
471	        return Ok(PublishOutcome::AlreadyPublished);
472	    }
473	    if output.success() {
474	        return Ok(PublishOutcome::Published);
475	    }
476	    if let Some(err) = detect_rate_limit(&combined) {
477	        return Err(err);
478	    }
479	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
480	        return Err(err);
481	    }
482	    Err(RegistryError::Other(format!(
483	        "cargo publish failed (exit {:?}): {}",
