514	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
515	/// [`RegistryError`].
516	///
517	/// Priority order (highest wins):
518	/// 1. Any `"already exist"` substring (from `--skip-existing`) →
519	///    [`PublishOutcome::AlreadyPublished`]. Partial skips (e.g. sdist
520	///    skipped, wheel uploaded) cannot be distinguished from a complete skip
521	///    by text alone, so any skip mention is conservatively classified as
522	///    already-published rather than over-reporting a fresh publish.
523	/// 2. Zero exit code with no skip mention → [`PublishOutcome::Published`].
524	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) →
525	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
526	///    retry-after duration.
527	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) →
528	///    [`RegistryError::AuthFailed`].
529	/// 5. Anything else → [`RegistryError::Other`].
530	fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
531	    let combined = combined_lower(output);
532	
533	    if combined.contains("already exist") {
534	        return Ok(PublishOutcome::AlreadyPublished);
535	    }
536	    if output.success() {
537	        return Ok(PublishOutcome::Published);
538	    }
539	    if let Some(err) = detect_rate_limit(&combined) {
540	        return Err(err);
541	    }
542	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
543	        return Err(err);
544	    }
545	    Err(RegistryError::Other(format!(
546	        "twine upload failed (exit {:?}): {}",
547	        output.exit_code,
548	        output.stderr.trim()
549	    )))

