 18 │ /// writer. When the plan contains no publishable packages, emits a clear
 19 │ /// "nothing to publish (dry run)" message; otherwise previews the plan.
 20 │ pub(crate) fn write_dry_run_text<W: std::io::Write>(
 21 │     plan: &callisto_model::PublishPlan,
 22 │     w: &mut W,
 23 │ ) -> std::io::Result<()> {
 24 │     let is_empty = plan.rust_crates.is_empty()
 25 │         && plan.npm_main_packages.is_empty()
 26 │         && plan.npm_platform_packages.is_empty()
 27 │         && plan.pypi_packages.is_empty();
 28 │     if is_empty {
 29 │         writeln!(w, "No packages published (dry run).")?;
 30 │     } else {
 31 │         writeln!(
 32 │             w,
 33 │             "Dry run: about to publish the following plan (nothing will be published):"
 34 │         )?;
 35 │         render::render_publish(plan, w)?;
 36 │     }
 37 │     Ok(())
 38 │ }
