235	    /// |--------------------|---------|----------------------------------------------|
236	    /// | `pnpm-lock.yaml`   | `pnpm`  | `publish --filter <name>`                    |
237	    /// | `yarn.lock`        | `yarn`  | `workspace <name> npm publish`               |
238	    /// | `bun.lockb`        | `bun`   | `publish`                                    |
239	    /// | (none)             | `npm`   | `publish --workspace <name>`                 |
240	    ///
241	    /// `tag` and `access` flags are appended after the base args by the caller
242	    /// ([`Self::npm_publish`]).
243	    fn build_npm_publish_command(
244	        &self,
245	        package_name: &str,
246	        tag: Option<&str>,
247	        access: Option<&str>,
248	    ) -> (String, Vec<String>) {
249	        let mut extra: Vec<String> = Vec::new();
250	        if let Some(t) = tag {
251	            extra.push("--tag".to_string());
252	            extra.push(t.to_string());
253	        }
254	        if let Some(av) = access {
255	            extra.push("--access".to_string());
256	            extra.push(av.to_string());
257	        }
258	
259	        if self.cwd.join("pnpm-lock.yaml").exists() {
260	            let mut args = vec![
261	                "publish".to_string(),
262	                "--filter".to_string(),
263	                package_name.to_string(),
264	            ];
265	            args.extend(extra);
266	            return ("pnpm".to_string(), args);
267	        }
268	
269	        if self.cwd.join("yarn.lock").exists() {
270	            let mut args = vec![
271	                "workspace".to_string(),
272	                package_name.to_string(),
273	                "npm".to_string(),
274	                "publish".to_string(),
275	            ];
276	            args.extend(extra);
277	            return ("yarn".to_string(), args);
278	        }
279	
280	        if self.cwd.join("bun.lockb").exists() {
281	            let mut args = vec!["publish".to_string()];
282	            args.extend(extra);
283	            return ("bun".to_string(), args);
284	        }
285	
286	        // Default: npm
287	        let mut args = vec![
288	            "publish".to_string(),
289	            "--workspace".to_string(),
290	            package_name.to_string(),
291	        ];
292	        args.extend(extra);
