296	    /// Publishes an npm package using the workspace package manager detected
297	    /// from lockfiles in the workspace root (`self.cwd`).
298	    ///
299	    /// - `tag`: when `Some`, appends `--tag <tag>` (e.g. `"next"` for pre-releases).

300	    ///   Without this, the package manager uses the implicit `"latest"` dist-tag.
301	    /// - `access`: when `Some(NpmAccess::Public)`, appends `--access public`;
302	    ///   when `Some(NpmAccess::Restricted)`, appends `--access restricted`;
303	    ///   when `None`, omits `--access` entirely so the package manager applies
304	    ///   its ecosystem default (`restricted` for `@scoped/packages`, `public`
305	    ///   for unscoped).
306	    fn npm_publish(
307	        &self,
308	        package: &PackageId,
309	        tag: Option<&str>,
310	        access: Option<&NpmAccess>,
311	    ) -> Result<PublishOutcome, RegistryError> {
312	        if package.name().starts_with('-') {
313	            return Err(RegistryError::Other(format!(
314	                "invalid package name `{}`: names may not begin with '-' (possible flag injection)",
315	                package.name()
316	            )));
317	        }
318	        let access_value = access.map(|a| match a {
319	            NpmAccess::Public => "public",
320	            NpmAccess::Restricted => "restricted",
321	        });
322	        let (program, args_owned) =
323	            self.build_npm_publish_command(package.name(), tag, access_value);
324	        let args_refs: Vec<&str> = args_owned.iter().map(|s| s.as_str()).collect();
325	
326	        // bun publish must run from the package directory — it has no
327	        // --filter or --workspace flag to target a named package. All other
328	        // package managers (pnpm --filter, yarn workspace, npm --workspace)
329	        // run from the workspace root and select the package by name.
330	        let effective_cwd = if program == "bun" {
331	            self.npm_pkg_dir
332	                .get(package.name())
333	                .map(|rel| self.cwd.join(rel))
334	                .unwrap_or_else(|| self.cwd.clone())
335	        } else {
336	            self.cwd.clone()
337	        };
338	
339	        let output = self.run_in(&program, &args_refs, &effective_cwd)?;
340	        classify_npm_publish_output(&output)
341	    }
