583	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
584	/// [`RegistryError`].
585	///
586	/// Priority order (highest wins):
587	/// 1. Any `"already exist"` substring (from `--skip-existing`) →
588	///    [`PublishOutcome::AlreadyPublished`]. Partial skips (e.g. sdist
589	///    skipped, wheel uploaded) cannot be distinguished from a complete skip
590	///    by text alone, so any skip mention is conservatively classified as
591	///    already-published rather than over-reporting a fresh publish.
592	/// 2. Zero exit code with no skip mention → [`PublishOutcome::Published`].
593	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) →
594	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
595	///    retry-after duration.
596	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) →
597	///    [`RegistryError::AuthFailed`].
598	/// 5. Anything else → [`RegistryError::Other`].
599	fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
600	    let combined = combined_lower(output);
601	
602	    if combined.contains("already exist") {
603	        return Ok(PublishOutcome::AlreadyPublished);
604	    }
605	    if output.success() {
606	        return Ok(PublishOutcome::Published);
607	    }
608	    if let Some(err) = detect_rate_limit(&combined) {
609	        return Err(err);
610	    }
611	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
612	        return Err(err);
613	    }
614	    Err(RegistryError::Other(format!(
615	        "twine upload failed (exit {:?}): {}",
616	        output.exit_code,
617	        output.stderr.trim()
618	    )))
619	}
