100	    severities: &BTreeMap<PackageId, Severity>,
101	    tags: &TagIndex,
102	    _pre: Option<&callisto_format::PreState>,
103	) -> Result<Version, GraphError> {
104	    let released: Vec<PackageId> = g
105	        .members(GroupMemberKind::Package)
106	        .filter_map(|m| match m {
107	            GroupMember::Package(ref id) => {
108	                if tags.last_tag(id).is_some() {
109	                    Some(id.clone())
110	                } else {
111	                    None
112	                }
113	            }
114	            _ => None,
115	        })
116	        .collect();
117	
118	    let mut max_sev = Severity::None;
119	    for m in g.members(GroupMemberKind::Package) {
120	        if let GroupMember::Package(ref id) = m {
121	            if let Some(&s) = severities.get(id) {
122	                if s > max_sev {
123	                    max_sev = s;
124	                }
125	            }
126	        }
127	    }
128	
129	    let aligned_base = if !released.is_empty() {
130	        base.get(&released[0])
131	            .cloned()
132	            .unwrap_or_else(|| Version::semver(1, 0, 0))
133	    } else {
134	        Version::semver(0, 0, 0)
135	    };
