143	/// platform, architecture, and (for Linux) ABI.
144	///
145	/// Returns `None` for any triple not in the known napi-rs target table.
146	pub fn triple_to_role(triple: &str) -> Option<ManifestRole> {
147	    let (platform, arch, abi) = match triple {
148	        "aarch64-apple-darwin" => ("darwin", "arm64", None),
149	        "x86_64-apple-darwin" => ("darwin", "x64", None),
150	        "x86_64-unknown-linux-gnu" => ("linux", "x64", Some("gnu")),
151	        "x86_64-unknown-linux-musl" => ("linux", "x64", Some("musl")),
152	        "aarch64-unknown-linux-gnu" => ("linux", "arm64", Some("gnu")),
153	        "aarch64-unknown-linux-musl" => ("linux", "arm64", Some("musl")),
154	        "x86_64-pc-windows-msvc" => ("win32", "x64", None),
155	        "i686-pc-windows-msvc" => ("win32", "ia32", None),
156	        "aarch64-pc-windows-msvc" => ("win32", "arm64", None),
157	        "armv7-unknown-linux-gnueabihf" => ("linux", "arm", Some("gnueabihf")),
158	        "x86_64-unknown-freebsd" => ("freebsd", "x64", None),
159	        "aarch64-linux-android" => ("android", "arm64", None),
160	        "armv7-linux-androideabi" => ("android", "arm", None),
161	        "riscv64gc-unknown-linux-gnu" => ("linux", "riscv64", Some("gnu")),
162	        "powerpc64le-unknown-linux-gnu" => ("linux", "ppc64", Some("gnu")),
163	        "s390x-unknown-linux-gnu" => ("linux", "s390x", Some("gnu")),
164	        "wasm32-wasip1" => ("wasi", "wasm32", None),
165	        "wasm32-unknown-unknown" => ("unknown", "wasm32", None),
166	        _ => return None,
167	    };
168	    Some(ManifestRole::Platform {
169	        platform: platform.to_string(),
170	        arch: arch.to_string(),
171	        abi: abi.map(str::to_string),
172	    })
173	}
