175	/// Reverse of `triple_to_role`: maps a `ManifestRole::Platform` back to the
176	/// canonical napi-rs target triple. Returns `None` for roles not in the table
177	/// (including `Canonical` and `Lockfile` roles).
178	pub fn role_to_triple(role: &ManifestRole) -> Option<String> {
179	    let ManifestRole::Platform {
180	        platform,
181	        arch,
182	        abi,
183	    } = role
184	    else {
185	        return None;
186	    };
187	    let triple = match (platform.as_str(), arch.as_str(), abi.as_deref()) {
188	        ("darwin", "arm64", None) => "aarch64-apple-darwin",
189	        ("darwin", "x64", None) => "x86_64-apple-darwin",
190	        ("linux", "x64", Some("gnu")) => "x86_64-unknown-linux-gnu",
191	        ("linux", "x64", Some("musl")) => "x86_64-unknown-linux-musl",
192	        ("linux", "arm64", Some("gnu")) => "aarch64-unknown-linux-gnu",
193	        ("linux", "arm64", Some("musl")) => "aarch64-unknown-linux-musl",
194	        ("win32", "x64", None) => "x86_64-pc-windows-msvc",
195	        ("win32", "ia32", None) => "i686-pc-windows-msvc",
196	        ("win32", "arm64", None) => "aarch64-pc-windows-msvc",
197	        ("linux", "arm", Some("gnueabihf")) => "armv7-unknown-linux-gnueabihf",
198	        ("freebsd", "x64", None) => "x86_64-unknown-freebsd",
199	        ("android", "arm64", None) => "aarch64-linux-android",
200	        ("android", "arm", None) => "armv7-linux-androideabi",
201	        ("linux", "riscv64", Some("gnu")) => "riscv64gc-unknown-linux-gnu",
202	        ("linux", "ppc64", Some("gnu")) => "powerpc64le-unknown-linux-gnu",
203	        ("linux", "s390x", Some("gnu")) => "s390x-unknown-linux-gnu",
204	        ("wasi", "wasm32", None) => "wasm32-wasip1",
205	        ("unknown", "wasm32", None) => "wasm32-unknown-unknown",
206	        _ => return None,
207	    };
208	    Some(triple.to_string())
209	}
