189	        &self,
190	        package: &PackageId,
191	        version: &Version,
192	    ) -> Result<bool, RegistryError> {
193	        let spec = format!("{}@{}", package.name(), version.render());
194	        let output = self.run("npm", &["view", &spec, "--json"])?;
195	
196	        if output.success() && !output.stdout_trimmed().is_empty() {
197	            return Ok(true);
198	        }
199	        if output.success() && output.stdout_trimmed().is_empty() {
200	            return Ok(false);
201	        }
202	
203	        let combined = combined_lower(&output);
204	        if combined.contains("e404")
205	            || combined.contains("etarget")
206	            || combined.contains("no matching version")
207	            || combined.contains("is not in this registry")
208	        {
209	            return Ok(false);
210	        }
211	
212	        if let Some(err) = detect_rate_limit(&combined) {
213	            return Err(err);
214	        }
215	        if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
216	            return Err(err);
217	        }
218	
219	        // Ambiguous failure: don't silently treat as "not published" — a
220	        // false-negative here would cause a duplicate publish attempt.
221	        Err(RegistryError::Other(format!(
222	            "npm view failed ambiguously (exit {:?}): {}",
223	            output.exit_code,
224	            output.stderr.trim()
225	        )))
226	    }
