    #[test]
    fn cargo_publish_proceeds_when_on_disk_version_matches_plan() {
        let dir = tempfile::tempdir().unwrap();

        let pkg_subdir = dir.path().join("crates/my-crate");
        std::fs::create_dir_all(&pkg_subdir).unwrap();
