        assert!(
            recorded[0].contains("crate-a"),
            "first progress message must mention crate-a; got: {:?}",
            recorded[0]
        );
        assert!(
            recorded[1].contains("crate-b"),
            "second progress message must mention crate-b; got: {:?}",
            recorded[1]
        );
    }
