19	
20	        match output {
21	            Ok(o) => {
22	                let out = CommandOutput {
23	                    exit_code: o.status.code(),
24	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
25	                    stderr: String::from_utf8_lossy(&o.stderr).into_owned(),
