42	    fn run_with_timeout(
43	        &self,
44	        program: &str,
45	        args: &[&str],
46	        cwd: &Path,
47	        timeout: Duration,
48	    ) -> Result<CommandOutput, CommandError> {
49	        let mut child = std::process::Command::new(program)
50	            .args(args)
51	            .current_dir(cwd)
52	            .stdin(Stdio::null())
53	            .stdout(Stdio::piped())
54	            .stderr(Stdio::piped())
55	            .spawn()
56	            .map_err(|e| {
57	                if e.kind() == std::io::ErrorKind::NotFound {
58	                    CommandError::NotFound {
59	                        program: program.to_string(),
60	                    }
61	                } else {
62	                    CommandError::Io {
63	                        program: program.to_string(),
64	                        message: e.to_string(),
65	                    }
66	                }
67	            })?;
68	
69	        // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
70	        // when the child produces output while we wait for it to exit.
71	        let stdout_handle = child.stdout.take().unwrap();
72	        let stderr_handle = child.stderr.take().unwrap();
73	
74	        let stdout_thread = std::thread::spawn(move || {
75	            let mut buf = String::new();
76	            drop(std::io::BufReader::new(stdout_handle).read_to_string(&mut buf));
77	            buf
78	        });
79	        let stderr_thread = std::thread::spawn(move || {
80	            let mut buf = String::new();
81	            drop(std::io::BufReader::new(stderr_handle).read_to_string(&mut buf));
82	            buf
83	        });
84	
85	        let deadline = Instant::now() + timeout;
86	        let status = loop {
87	            match child.try_wait().map_err(|e| CommandError::Io {
88	                program: program.to_string(),
89	                message: e.to_string(),
90	            })? {
91	                Some(s) => break s,
92	                None => {
93	                    if Instant::now() >= deadline {
94	                        drop(child.kill());
95	                        drop(child.wait());
96	                        drop(stdout_thread.join());
97	                        drop(stderr_thread.join());
98	                        return Err(CommandError::TimedOut {
99	                            program: program.to_string(),
100	                            seconds: timeout.as_secs(),
101	                        });
102	                    }
103	                    std::thread::sleep(Duration::from_millis(50));
104	                }
105	            }
106	        };
107	
108	        let stdout = stdout_thread.join().unwrap_or_default();
109	        let stderr = stderr_thread.join().unwrap_or_default();
110	
111	        let out = CommandOutput {
112	            exit_code: status.code(),
113	            stdout,
114	            stderr: stderr.clone(),
115	        };
116	        if !out.stderr.is_empty() {
117	            eprint!("{}", out.stderr);
118	        }
