300	impl CommitSha {
301	    /// Parses a 40-character hexadecimal Git commit SHA, trimming surrounding whitespace.
302	    ///
303	    /// # Errors
304	    ///
305	    /// Returns `Err(ModelError::InvalidCommitSha)` if the trimmed input is not exactly 40 ASCII hex digits.
306	    pub fn parse(s: &str) -> Result<Self, ModelError> {
307	        let trimmed = s.trim();
308	        if trimmed.len() != 40 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
309	            return Err(ModelError::InvalidCommitSha {
310	                raw: s.to_string(),
311	                reason: "must be exactly 40 hexadecimal characters".to_string(),
312	            });
313	        }
314	        Ok(CommitSha(trimmed.to_lowercase()))
315	    }
316	
317	    /// Returns the full 40-character lowercase hex SHA.
318	    pub fn as_str(&self) -> &str {
319	        &self.0
320	    }
321	
322	    /// Returns the first 7 characters of the SHA, matching git's short-ref convention.
323	    pub fn short(&self) -> &str {
324	        &self.0[..7]
325	    }
326	}
